package com.mirigangneung.course.recommendation; import com.mirigangneung.place.domain.Place; import org.springframework.stereotype.Component; import java.util.*;
@Component public class RuleBasedCourseRecommendationEngine implements CourseRecommendationEngine {public List<Place> recommend(List<Place> candidates,Place one,List<String>types,String companion,String duration){List<Place> out=new ArrayList<>();out.add(one);candidates.stream().filter(p->!samePlace(p,one)).filter(p->p.getLatitude()!=null&&p.getLongitude()!=null).sorted(Comparator.comparingDouble(p->distance(one,p))).limit("night1".equals(duration)?4:3).forEach(out::add);return out;}private boolean samePlace(Place a,Place b){return a==b||(a.getId()!=null&&a.getId().equals(b.getId()))||a.getTourContentId().equals(b.getTourContentId());}private double distance(Place a,Place b){double dx=a.getLatitude()-b.getLatitude(),dy=a.getLongitude()-b.getLongitude();return dx*dx+dy*dy;}}
